-- Domain weights, from CompTIA's 220-1201 exam page.
update cert_domains d
set exam_weight = v.weight
from (values
  ('1.0', 13),
  ('2.0', 23),
  ('3.0', 25),
  ('4.0', 11),
  ('5.0', 28)
) as v(domain_number, weight)
where d.certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101') and d.domain_number = v.domain_number;

-- The 220-1101 objectives step aside, so V15's can take their codes.
update cert_sub_objectives s
set code = 'v14-' || s.code
from cert_domains d
where s.domain_id = d.id and d.certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101');

-- The 220-1201 objectives, in our own words.
insert into cert_sub_objectives (domain_id, code, title, sort_order)
select d.id, v.code, v.title, v.sort_order
from (values
  ('1.0', '1.1', 'Monitor mobile device hardware and use the right replacement techniques', 1),
  ('1.0', '1.2', 'Accessories and connection options for mobile devices', 2),
  ('1.0', '1.3', 'Configure mobile device network connectivity and support applications', 3),
  ('2.0', '2.1', 'TCP and UDP ports, protocols and what they''re for', 1),
  ('2.0', '2.2', 'Wireless networking technologies', 2),
  ('2.0', '2.3', 'Services that networked hosts provide', 3),
  ('2.0', '2.4', 'Common network configuration concepts', 4),
  ('2.0', '2.5', 'Common networking hardware devices', 5),
  ('2.0', '2.6', 'Configure basic wired and wireless SOHO networks', 6),
  ('2.0', '2.7', 'Internet connection types, network types and their characteristics', 7),
  ('2.0', '2.8', 'Networking tools and what they''re for', 8),
  ('3.0', '3.1', 'Display components and attributes', 1),
  ('3.0', '3.2', 'Cable types and their connectors, features and purposes', 2),
  ('3.0', '3.3', 'RAM characteristics', 3),
  ('3.0', '3.4', 'Storage devices', 4),
  ('3.0', '3.5', 'Install and configure motherboards, CPUs and add-on cards', 5),
  ('3.0', '3.6', 'Install the right power supply', 6),
  ('3.0', '3.7', 'Deploy and configure multifunction devices, printers and their settings', 7),
  ('3.0', '3.8', 'Maintain laser, inkjet, thermal and impact printers', 8),
  ('4.0', '4.1', 'Virtualization concepts', 1),
  ('4.0', '4.2', 'Cloud computing concepts', 2),
  ('5.0', '5.1', 'Troubleshoot motherboards, RAM, CPUs and power', 1),
  ('5.0', '5.2', 'Troubleshoot drive and RAID issues', 2),
  ('5.0', '5.3', 'Troubleshoot video, projector and display issues', 3),
  ('5.0', '5.4', 'Troubleshoot common mobile device issues', 4),
  ('5.0', '5.5', 'Troubleshoot network issues', 5),
  ('5.0', '5.6', 'Troubleshoot printer issues', 6)
) as v(domain_number, code, title, sort_order)
join cert_domains d on d.domain_number = v.domain_number and d.certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101');

