-- Domain weights, from CompTIA's 220-1202 exam page.
update cert_domains d
set exam_weight = v.weight
from (values
  ('1.0', 28),
  ('2.0', 28),
  ('3.0', 23),
  ('4.0', 21)
) as v(domain_number, weight)
where d.certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102') and d.domain_number = v.domain_number;

-- The 220-1102 objectives step aside, so V15's can take their codes.
update cert_sub_objectives s
set code = 'v14-' || s.code
from cert_domains d
where s.domain_id = d.id and d.certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102');

