-- Questions whose whole objective left the exam: inactive, with no objective.
update cert_questions q
set is_active = false, sub_objective_id = null, updated_at = now()
from cert_sub_objectives s
join cert_domains d on d.id = s.domain_id and d.certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102')
where q.sub_objective_id = s.id and s.code like 'v14-%';

-- Correction.
update cert_questions set
  question_text = 'A Linux technician installs packages on a Red Hat Enterprise Linux (RHEL) or Fedora system. Which package manager command is used on these distributions?',
  options = '[{"text":"apt-get","is_correct":false},{"text":"pacman","is_correct":false},{"text":"dnf","is_correct":true},{"text":"dpkg","is_correct":false}]'::jsonb,
  correct_index = 2,
  explanation = 'dnf is the package manager on Red Hat Enterprise Linux 8 and later and on Fedora; it replaced yum, which remains only as a compatibility command. apt-get and dpkg belong to Debian and Ubuntu, and pacman to Arch Linux.',
  updated_at = now()
where id = '3b7aee31-e8a4-44e0-b880-51ef6453254a';

-- The 220-1102 objectives, now unused.
delete from cert_sub_objectives s
using cert_domains d
where s.domain_id = d.id and d.certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102') and s.code like 'v14-%';

do $$
begin
  if exists (select 1 from cert_questions where certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102') and is_active and sub_objective_id is null) then
    raise exception '220-1202: an active question has no objective';
  end if;
  if (select count(*) from cert_questions where certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102') and is_active) <> 516 then
    raise exception '220-1202: expected 516 active questions';
  end if;
end $$;

-- The exam itself: enrollments, Pro and history stay on the same row.
update certifications
set slug = 'a-plus-core2-220-1202', exam_code = '220-1202', passing_score = 700
where slug = 'a-plus-core2-220-1102';

-- Saved paths may use the V15 slugs. Rows still on the old ones are moved,
-- answers re-keyed, by scripts/a-plus-v15/migrate-path-progress.ts.
alter table path_progress drop constraint if exists path_progress_cert_slug_check;
alter table path_progress add constraint path_progress_cert_slug_check check (cert_slug in (
  'security-plus-sy0-701', 'network-plus-n10-009',
  'a-plus-core1-220-1101', 'a-plus-core2-220-1102',
  'a-plus-core1-220-1201', 'a-plus-core2-220-1202'
));

commit;

